Get-ChildItem -Path $ClientCharacter -Recurse -Filter *.img | ForEach-Object {
    $n = $_.BaseName -replace "^0+", ""
    if ($n -match "^\d+$") { $have[[int]$n] = $_.FullName }
}
Write-Host "客户端 Data/Character 下共有 $($have.Count) 个 img"
$missing = $ids | Where-Object { -not $have.ContainsKey($_) }
Write-Host "bot 外观用到 $($ids.Count) 个 ID，其中客户端缺失 $($missing.Count) 个" -ForegroundColor Yellow
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Host "  缺失 $_" -ForegroundColor Red } }
else { Write-Host "客户端资源齐全，可排除贴图缺失。" -ForegroundColor Green }
